// lo — ລາວ (laosiano).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// ---------------------------------------------------------------------------------------------------
// CONFIANÇA MÉDIA, abaixo da do tailandês. O laosiano é parente próximo do tailandês e tem bem menos
// texto de onde eu tenha aprendido — e o erro provável não é frase sem sentido, é FRASE TAILANDESA
// ESCRITA EM LETRA LAO: palavra que só o tailandês usa, ou a grafia antiga com consoante muda que a
// reforma lao tirou. Ninguém da dupla lê nenhuma das duas. Se aparecer quem fale laosiano, a revisão
// vale mais que este arquivo.
// ---------------------------------------------------------------------------------------------------
//
// O ESPAÇO NÃO SEPARA PALAVRA, como no tailandês (ver th.ts, que mediu a quebra de linha): as
// palavras vão coladas, e o espaço faz o trabalho da vírgula — separa oração, destaca número, isola
// palavra estrangeira. O PONTO FINAL também não entra, embora a chave tenha.
//
// TRATAMENTO: **ເຈົ້າ**, o "você" de igual para igual; ທ່ານ seria o "senhor" e fica de fora. E, como
// no tailandês, o pronome some quando o contexto basta. Diferente do tailandês, a partícula de
// cortesia do laosiano (ເຈົ້າ no fim da resposta) não diz o sexo de quem fala — mas interface também
// não a usa, então não entra.
//
// GÊNERO: NENHUM. Nem no "você", nem no "ele/ela" (ລາວ), nem no verbo.
//
// GRAFIA: a lao moderna, a das ligaduras ໜ ໝ ຫຼ e sem as consoantes mudas que o tailandês mantém.
//
// A ESCRITA TEM FONTE PRÓPRIA: 'lao' → Noto Sans Lao (FONTE_DA_ESCRITA, em idiomas.ts), baixada só
// quando a pessoa escolhe a língua.
//
// ALGARISMOS: os lao (໐໑໒…) existem, mas o Intl desenha 0-9 — o Chrome não tem dados do laosiano e o
// Syden cai nos latinos (ver algarismos.ts, que só força os próprios para birmanês e nepalês). Os
// números deste arquivo vão com 0-9, para não haver duas numerações na mesma tela. E o laosiano não
// marca plural: "1 mensagem" e "{n} mensagens" caem na mesma forma.
//
// VOCABULÁRIO, decidido uma vez: comunidade = ຊຸມຊົນ, canal = ຊ່ອງ, sala de voz = ຫ້ອງສຽງ, chamada =
// ການໂທ, conversa = ການສົນທະນາ, mensagem = ຂໍ້ຄວາມ, senha = ລະຫັດຜ່ານ, lixeira = ຖັງຂີ້ເຫຍື້ອ, tópico =
// ກະທູ້, conta = ບັນຊີ, administrador = ຜູ້ດູແລ, dono = ເຈົ້າຂອງ, cargo = ບົດບາດ, convite = ຄຳເຊີນ,
// perfil = ໂປຣໄຟລ໌, transmissão = ສະຕຣີມ, tela = ໜ້າຈໍ, membro = ສະມາຊິກ, pacote = ຊຸດ, enquete =
// ແບບສຳຫຼວດ, denúncia = ການລາຍງານ, vila = ໝູ່ບ້ານ, guarda-roupa = ຕູ້ເສື້ອຜ້າ, selo = ຕາປະທັບ (o da
// comunidade), insígnia = ເຄື່ອງໝາຍ (a da pessoa), recado (da tela de boas-vindas e do aviso) = ປະກາດ.

