  'Desconectar': 'ຕັດການເຊື່ອມຕໍ່',
  'Descrição': 'ຄຳອະທິບາຍ',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.':
    'ເມື່ອປິດ ສະຕຣີມຂອງຄົນໃນຫ້ອງຈະສະແດງເປັນຄຳເຊີນ ແລະຈະເລີ່ມດາວໂຫຼດເມື່ອເຈົ້າຄລິກ ເບິ່ງ ເທົ່ານັ້ນ ຊ່ວຍປະຢັດອິນເຕີເນັດແລະໂປຣເຊສເຊີ — ໂດຍສະເພາະໃນຫ້ອງທີ່ເຕັມ',
  'Desligar câmera': 'ປິດກ້ອງ',
  'Deste servidor': 'ຈາກເຊີບເວີນີ້',
  'Diga o e-mail da sua conta e mandamos um link para escolher outra.':
    'ບອກອີເມວຂອງບັນຊີເຈົ້າ ແລ້ວພວກເຮົາຈະສົ່ງລິ້ງໃຫ້ເລືອກລະຫັດຜ່ານໃໝ່',
  'Digite sua senha para confirmar': 'ພິມລະຫັດຜ່ານເພື່ອຢືນຢັນ',
  'Disponível': 'ອອນລາຍ',
  'Do laranja ao vermelho, como carvão aceso.': 'ຈາກສີສົ້ມຫາສີແດງ ຄືຖ່ານທີ່ກຳລັງລຸກ',
  'Dois emojis com o mesmo nome: cada um precisa do seu.': 'ອີໂມຈິສອງອັນມີຊື່ດຽວກັນ: ແຕ່ລະອັນຕ້ອງມີຊື່ຂອງຕົນເອງ',
  'Dono': 'ເຈົ້າຂອງ',
  'Dono da comunidade': 'ເຈົ້າຂອງຊຸມຊົນ',
  'Dourado com brilho que passa devagar.': 'ສີຄຳທີ່ມີແສງເຫຼື້ອມຜ່ານໄປຊ້າໆ',
  'Durante uma chamada, esse botão toca estes sons para todos na sala. Instale pacotes prontos ou envie os seus; o que é seu favorito fica na frente do painel.':
    'ລະຫວ່າງໂທ ປຸ່ມນີ້ຈະຫຼິ້ນສຽງເຫຼົ່ານີ້ໃຫ້ທຸກຄົນໃນຫ້ອງ ຕິດຕັ້ງຊຸດສຳເລັດຮູບ ຫຼື ສົ່ງຂອງເຈົ້າເອງ ອັນທີ່ມັກຈະຢູ່ທາງໜ້າຂອງແຜງ',
  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.':
    'ນີ້ແມ່ນສິ່ງທຳອິດທີ່ຄົນເຫັນເມື່ອເຂົ້າຊຸມຊົນ ພຽງເທື່ອດຽວ ຖ້າບໍ່ມີ ເຂົາຈະໄປຮອດລາຍການຊ່ອງໂດຍກົງ',
  'É assim que os outros veem você na lista e nas conversas.': 'ນີ້ແມ່ນວິທີທີ່ຄົນອື່ນເຫັນເຈົ້າໃນລາຍການແລະໃນການສົນທະນາ',
  'É isto que os seus amigos veem aqui embaixo do quarto. O que eles escreverem chega para você como conversa privada, com 💡 na frente — e o Syden já responde agradecendo na hora. Quando a ideia entrar no app, use o joinha na mensagem: do lado deles cai confete e a medalha aparece no perfil.':
    'ນີ້ແມ່ນສິ່ງທີ່ໝູ່ຂອງເຈົ້າເຫັນຢູ່ລຸ່ມຫ້ອງ ສິ່ງທີ່ເຂົາຂຽນຈະມາຫາເຈົ້າເປັນການສົນທະນາສ່ວນຕົວ ມີ 💡 ຢູ່ທາງໜ້າ — ແລະ Syden ຈະຕອບຂອບໃຈທັນທີ ເມື່ອແນວຄິດເຂົ້າໄປໃນແອັບ ໃຫ້ກົດ 👍 ທີ່ຂໍ້ຄວາມ: ຝ່າຍເຂົາຈະມີເຈ້ຍສີຕົກລົງມາ ແລະຫຼຽນຈະສະແດງໃນໂປຣໄຟລ໌',
  'é o que você está enviando': 'ແມ່ນສິ່ງທີ່ເຈົ້າກຳລັງສົ່ງ',
  'É o seu único jeito de entrar. Defina uma senha antes de desligar.': 'ນີ້ແມ່ນທາງດຽວທີ່ເຈົ້າເຂົ້າໄດ້ ຕັ້ງລະຫັດຜ່ານກ່ອນຕັດການເຊື່ອມຕໍ່',
  'E-mail': 'ອີເມວ',
  'Eco de lugar grande e vazio.': 'ສຽງສະທ້ອນຂອງບ່ອນກວ້າງທີ່ວ່າງເປົ່າ',
