  'Encerrar a apresentação': 'ຈົບການນຳສະເໜີ',
  'Endereço': 'ທີ່ຢູ່',
  'Endereço guardado. Confira a sua caixa de entrada para confirmar.': 'ບັນທຶກທີ່ຢູ່ແລ້ວ ກວດເບິ່ງກ່ອງຈົດໝາຍເພື່ອຢືນຢັນ',
  'Endereço guardado. O envio de e-mail ainda não está ligado neste servidor, então o link de confirmação ficou no registro do servidor.':
    'ບັນທຶກທີ່ຢູ່ແລ້ວ ເຊີບເວີນີ້ຍັງບໍ່ໄດ້ເປີດການສົ່ງອີເມວ ລິ້ງຢືນຢັນຈຶ່ງຢູ່ໃນບັນທຶກຂອງເຊີບເວີ',
  'Enfeites, sons e emojis': 'ເຄື່ອງປະດັບ ສຽງ ແລະອີໂມຈິ',
