  'Contadores': 'ຕົວນັບ',
  'Em chamada': 'ຢູ່ໃນການໂທ',
  'Em chamada: {n}': 'ຢູ່ໃນການໂທ: {n}',
  'Membros: {n}': 'ສະມາຊິກ: {n}',
  'Online agora': 'ອອນລາຍຕອນນີ້',
  'Online agora: {n}': 'ອອນລາຍຕອນນີ້: {n}',
  'Os números aparecem no alto da lista de canais, para todo mundo, e mudam sozinhos.': 'ຕົວເລກຈະສະແດງຢູ່ເທິງລາຍຊື່ຊ່ອງໃຫ້ທຸກຄົນເຫັນ ແລະ ອັບເດດເອງ.',
  'Criar uma sala para cada pessoa que entrar': 'ສ້າງຫ້ອງໃຫ້ທຸກຄົນທີ່ເຂົ້າມາ',
  'Entre para criar a sua sala': 'ເຂົ້າມາເພື່ອສ້າງຫ້ອງຂອງເຈົ້າ',
  'Limite de pessoas': 'ຈຳກັດຄົນ',
  'Quantas pessoas cabem (0 = sem limite)': 'ເຂົ້າໄດ້ຈັກຄົນ (0 = ບໍ່ຈຳກັດ)',
  'Canal de destaques': 'ຊ່ອງຂໍ້ຄວາມເດັ່ນ',
  'Destaques': 'ຂໍ້ຄວາມເດັ່ນ',
  'Estrelas necessárias': 'ດາວທີ່ຕ້ອງການ',
  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'ເມື່ອຂໍ້ຄວາມໄດ້ຮັບດາວ ⭐ ພຽງພໍ Syden ຈະໂພສມັນໃນຊ່ອງຂໍ້ຄວາມເດັ່ນ. ດາວຂອງຜູ້ຂຽນເອງບໍ່ນັບ ແລະ ການລຶບຂໍ້ຄວາມຈະລຶບຂໍ້ຄວາມເດັ່ນນຳ.',
  '🎉 Resultado do sorteio de {premio}: {vencedores}. Parabéns!': '🎉 ຜົນການຈັບສະຫຼາກ {premio}: {vencedores}. ຂໍສະແດງຄວາມຍິນດີ!',
  '🎉 Sorteio: {premio}! Reaja com 🎉 para participar. O resultado sai em {quando}.': '🎉 ຈັບສະຫຼາກ: {premio}! ກົດ 🎉 ເພື່ອເຂົ້າຮ່ວມ. ຜົນຈະອອກ {quando}.',
  'Começar o sorteio': 'ເລີ່ມຈັບສະຫຼາກ',
  'Encerrar agora': 'ປິດດຽວນີ້',
  'Ganhadores': 'ຈຳນວນລາງວັນ',
  'Ninguém participou.': 'ບໍ່ມີໃຜເຂົ້າຮ່ວມ.',
  'Novo sorteio': 'ຈັບສະຫຼາກໃໝ່',
  'O sorteio de {premio} terminou sem participantes.': 'ການຈັບສະຫຼາກ {premio} ຈົບລົງໂດຍບໍ່ມີຜູ້ເຂົ້າຮ່ວມ.',
  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Syden ປະກາດລາງວັນໃນຊ່ອງ ແລະ ຜູ້ທີ່ຢາກເຂົ້າຮ່ວມກົດ 🎉. ເມື່ອຮອດເວລາ ຈະຈັບສະຫຼາກລະຫວ່າງຜູ້ທີ່ກົດ ແລະ ໂພສຜົນ.',
  'Participantes: {n}': 'ຜູ້ເຂົ້າຮ່ວມ: {n}',
