  'Mês': 'ເດືອນ',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'ໃນວັນເກີດຂອງຜູ້ທີ່ລົງວັນທີໄວ້ Syden ຈະໂພສຄຳອວຍພອນໃນຊ່ອງທີ່ເລືອກ. ໃຊ້ {pessoa} ແທນຊື່.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'ສະເພາະວັນ ແລະ ເດືອນ ບໍ່ເຄີຍມີປີ. ຊຸມຊົນທີ່ແຈ້ງວັນເກີດຈະອວຍພອນໃນມື້ນັ້ນ. ເປັນທາງເລືອກ ແລະ ລຶບໄດ້ທຸກເວລາ.',
