  'Na hora marcada, o Syden publica o texto no canal. Dá para repetir todo dia ou toda semana.': 'ຮອດເວລາທີ່ກຳນົດ Syden ຈະໂພສຂໍ້ຄວາມໃນຊ່ອງ. ສາມາດເຮັດຊ້ຳທຸກມື້ ຫຼື ທຸກອາທິດ.',
