  'Alguém escreve o comando no começo de uma mensagem, como !regras, e o Syden responde no canal com o texto que você cadastrar. Use {pessoa} para o nome de quem pediu e {comunidade} para o nome da comunidade.': 'ມີຄົນຂຽນຄຳສັ່ງຢູ່ຕົ້ນຂໍ້ຄວາມ ເຊັ່ນ !regras ແລ້ວ Syden ຈະຕອບໃນຊ່ອງດ້ວຍຂໍ້ຄວາມທີ່ທ່ານລົງໄວ້. ໃຊ້ {pessoa} ສຳລັບຊື່ຜູ້ຂໍ ແລະ {comunidade} ສຳລັບຊື່ຊຸມຊົນ.',
