  'Você está em silêncio em {comunidade} até {hora}.': 'ທ່ານຢູ່ໃນໂໝດງຽບໃນ {comunidade} ຮອດ {hora}.',
  'Você está em silêncio nesta comunidade até {hora}.': 'ທ່ານຢູ່ໃນໂໝດງຽບໃນຊຸມຊົນນີ້ຮອດ {hora}.',
  'Você recebeu uma advertência em {comunidade}: {motivo}': 'ທ່ານໄດ້ຮັບການເຕືອນໃນ {comunidade}: {motivo}',
  'Barrar excesso de mensagens (mais de 5 em 10 segundos)': 'ຢຸດຂໍ້ຄວາມຫຼາຍເກີນ (ຫຼາຍກວ່າ 5 ໃນ 10 ວິນາທີ)',
