  'Modo lento: uma mensagem a cada {tempo}.': 'ໂໝດຊ້າ: ໜຶ່ງຂໍ້ຄວາມທຸກ {tempo}.',
  'Palavras proibidas': 'ຄຳຕ້ອງຫ້າມ',
  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'ແຕ່ລະຄົນຕ້ອງລໍຖ້າດົນປານໃດລະຫວ່າງຂໍ້ຄວາມໃນຊ່ອງ.',
  'Regras': 'ກົດລະບຽບ',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'ກົດທີ່ Syden ນຳໃຊ້ເອງ ກ່ອນຂໍ້ຄວາມຈະປາກົດ. ບໍ່ມີຜົນກັບຜູ້ຄຸ້ມຄອງ. ຂໍ້ຄວາມທີ່ຖືກບລັອກຈະກັບຄືນຫາຜູ້ຂຽນພ້ອມເຫດຜົນ ແລະ ບໍ່ມີໃຜອື່ນເຫັນ.',
  'Salvo.': 'ບັນທຶກແລ້ວ.',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'ແຖວລະອັນ. ນັບທັງຄຳ ໂດຍບໍ່ສົນເຄື່ອງໝາຍ ຫຼື ຕົວພິມໃຫຍ່: ການຫ້າມຄຳໜຶ່ງ ບໍ່ໄດ້ບລັອກຄຳທີ່ຍາວກວ່າທີ່ພຽງແຕ່ມີຄຳນັ້ນ.',
  '{faltam} pontos para o nível {proximo}.': 'ອີກ {faltam} ຄະແນນເຖິງລະດັບ {proximo}.',
  'Adicionar recompensa': 'ເພີ່ມລາງວັນ',
  'Cada mensagem vale pontos (uma por minuto), e cada minuto numa sala com mais alguém também. Quem sobe de nível recebe um aviso só para si.': 'ທຸກຂໍ້ຄວາມໄດ້ຄະແນນ (ນາທີລະເທື່ອ) ແລະ ທຸກນາທີໃນຫ້ອງກັບຄົນອື່ນກໍໄດ້ຄືກັນ. ຜູ້ທີ່ຂຶ້ນລະດັບຈະໄດ້ຮັບແຈ້ງເຕືອນສະເພາະຕົນເອງ.',
  'Cargo da recompensa': 'ບົດບາດລາງວັນ',
  'Crie um cargo acima para usar como recompensa.': 'ສ້າງບົດບາດຂ້າງເທິງເພື່ອໃຊ້ເປັນລາງວັນ.',
