  'Tirar a recompensa do nível {nivel}': 'ເອົາລາງວັນລະດັບ {nivel} ອອກ',
  'Você ainda não tem pontos aqui. Converse ou entre numa sala com alguém.': 'ທີ່ນີ້ທ່ານຍັງບໍ່ມີຄະແນນ. ລົມກັນ ຫຼື ເຂົ້າຫ້ອງກັບໃຜຜູ້ໜຶ່ງ.',
