  'Grafite': 'ກຣາໄຟດ໌',
  'Cinza neutro, quase preto, com verde-água.': 'ສີເທົາກາງ, ເກືອບດຳ, ກັບສີຂຽວທະເລ.',
  'Alto contraste': 'ຄວາມຄົມຊັດສູງ',
  'Preto, branco e amarelo, para ler sem esforço.': 'ດຳ, ຂາວ ແລະ ເຫຼືອງ, ອ່ານງ່າຍ.',
  'A paleta vale no tema escuro. Com o sol ligado, o Syden usa o tema claro.': 'ຊຸດສີໃຊ້ກັບຮູບແບບມືດ. ເມື່ອເປີດຕາເວັນ, Syden ໃຊ້ຮູບແບບແຈ້ງ.',
  'Não deu para entrar agora. Tente de novo.': 'ຕອນນີ້ເຂົ້າບໍ່ໄດ້. ລອງໃໝ່ອີກ.',
