  'ERRO — Algo deu errado do nosso lado': 'ຂໍ້ຜິດພາດ — ມີບາງຢ່າງຜິດພາດຈາກຝັ່ງພວກເຮົາ',
  'O Syden travou': 'Syden ຄ້າງ',
