  'Ninguém cantou ainda. Conta quando alguém põe uma música com a turma na sala.': "ຍັງບໍ່ມີໃຜຮ້ອງ. ນັບເມື່ອມີຄົນເປີດເພງໃນຂະນະທີ່ກຸ່ມຢູ່ໃນຫ້ອງ.",
