  'Aparece no seu cartão de perfil, para quem fala um idioma achar quem o estuda. É opcional.': "ສະແດງຢູ່ໃນບັດໂປຣໄຟລ໌ຂອງເຈົ້າ ເພື່ອໃຫ້ຄົນທີ່ເວົ້າພາສາໃດໜຶ່ງຊອກຫາຄົນທີ່ກຳລັງຮຽນມັນໄດ້. ບໍ່ບັງຄັບ.",
