  'Quem está aqui não vê as suas mensagens nem você as dele, não consegue abrir conversa privada com você e não pode te mandar pedido de amizade.':
    'ຄົນໃນນີ້ຈະບໍ່ເຫັນຂໍ້ຄວາມຂອງເຈົ້າ ແລະເຈົ້າກໍບໍ່ເຫັນຂອງເຂົາ ເຂົາເປີດການສົນທະນາສ່ວນຕົວກັບເຈົ້າບໍ່ໄດ້ ແລະສົ່ງຄຳຂໍເປັນໝູ່ຫາເຈົ້າບໍ່ໄດ້',
