    'ຖ້າມີບັນຊີທີ່ໃຊ້ທີ່ຢູ່ນີ້ ລິ້ງເລືອກລະຫັດຜ່ານໃໝ່ໄດ້ສົ່ງໄປແລ້ວ ໃຊ້ໄດ້ 1 ຊົ່ວໂມງ',
