  'Só quem administra pode instalar ou tirar.': 'ມີແຕ່ຜູ້ດູແລທີ່ຕິດຕັ້ງ ຫຼື ເອົາອອກໄດ້',
  'Só quem administra vê este bloco': 'ມີແຕ່ຜູ້ດູແລທີ່ເຫັນສ່ວນນີ້',
