  'Nenhum som ainda. Adicione um abaixo, ou instale um pacote em Configurações → Soundboard.': 'ຍັງບໍ່ມີສຽງ ເພີ່ມໄດ້ຢູ່ລຸ່ມນີ້ ຫຼື ຕິດຕັ້ງຊຸດໃນ ການຕັ້ງຄ່າ → ແຜງສຽງ',
