  'Opções da transmissão': 'ຕົວເລືອກສະຕຣີມ',
  'Compartilhar tela': 'ແບ່ງປັນໜ້າຈໍ',
  'Trocar para…': 'ປ່ຽນເປັນ…',
  'O que compartilhar?': 'ຈະແບ່ງປັນຫຍັງ?',
  'O som do computador vai junto sozinho.': 'ສຽງຂອງຄອມພິວເຕີຈະໄປນຳເອງ',
  'No navegador, o som só vai se você marcar a caixinha de áudio na janelinha que abrir. No app do Syden ele vai sozinho.': 'ໃນບຣາວເຊີ ສຽງຈະໄປກໍຕໍ່ເມື່ອເຈົ້າໝາຍຊ່ອງສຽງໃນໜ້າຕ່າງນ້ອຍທີ່ເປີດຂຶ້ນ ໃນແອັບ Syden ສຽງຈະໄປເອງ',
