  'Ao lado de um objeto de tamanho conhecido aparece outro, e cada um aumenta ou diminui esse outro até achar o tamanho certo. Quem chegar mais perto ganha mais pontos.': 'ຢູ່ຂ້າງວັດຖຸທີ່ຮູ້ຂະໜາດ ຈະມີອີກວັດຖຸໜຶ່ງປາກົດ ແລະທຸກຄົນຂະຫຍາຍ ຫຼື ຫຍໍ້ມັນຈົນເຫັນວ່າໄດ້ຂະໜາດທີ່ຖືກຕ້ອງ. ຄົນທີ່ໃກ້ທີ່ສຸດໄດ້ຄະແນນຫຼາຍທີ່ສຸດ.',
