  'Preencha todas as categorias antes de parar.': 'ຕື່ມທຸກໝວດກ່ອນຈະຢຸດ.',
  'STOP': 'STOP',
  '{nome} apertou STOP!': '{nome} ກົດ STOP!',
  'Clique numa resposta que não vale. Ela cai se mais da metade concordar.': 'ຄລິກຄຳຕອບທີ່ບໍ່ນັບ. ມັນຈະຖືກຕັດອອກຖ້າຫຼາຍກວ່າເຄິ່ງໜຶ່ງເຫັນດີ.',
