  'Você terminou! Agora é torcer pelos outros.': 'ເຈົ້າເຮັດສຳເລັດແລ້ວ! ຕອນນີ້ເຊຍຄົນອື່ນໄດ້ເລີຍ.',
  'Outros jogos': 'ເກມອື່ນ',
  'Stop': 'Stop',
  'Sai uma letra e cada um escreve uma palavra com ela em cada categoria. Quem completar primeiro aperta STOP, e a turma decide o que vale.': 'ຈະມີຕົວອັກສອນໜຶ່ງອອກມາ ແລະ ແຕ່ລະຄົນຂຽນຄຳທີ່ຂຶ້ນຕົ້ນດ້ວຍຕົວນັ້ນໃນທຸກໝວດ. ຄົນທີ່ຕື່ມຄົບກ່ອນກົດ STOP ແລະ ໝູ່ໆຕັດສິນວ່າອັນໃດນັບ.',
  'Sudoku': 'ຊູໂດກຸ',
  'Todo mundo recebe o mesmo sudoku, e a sala vê quem está mais perto de terminar.': 'ທຸກຄົນໄດ້ຊູໂດກຸອັນດຽວກັນ ແລະ ຄົນໃນຫ້ອງຈະເຫັນວ່າໃຜໃກ້ຈະແລ້ວທີ່ສຸດ.',
  'Cinco em linha': 'ຫ້າເມັດຮຽງ',
  'Duas pessoas põem pedras no tabuleiro, uma de cada vez. Vence quem fizer cinco seguidas. A sala assiste.': 'ສອງຄົນຜັດກັນວາງເມັດເທິງກະດານ. ຄົນທີ່ວາງໄດ້ຫ້າເມັດຮຽງກັນກ່ອນຊະນະ. ຄົນໃນຫ້ອງເບິ່ງຢູ່.',
  'Mancala': 'ມັນຄາລາ',
  'O jogo de semear: pegue as sementes de uma casa e espalhe uma por casa. Vence quem guardar mais no depósito. A sala assiste.': 'ເກມຫວ່ານເມັດ: ເອົາເມັດຈາກຂຸມໜຶ່ງ ແລ້ວຫວ່ານໃສ່ຂຸມຕໍ່ໄປຂຸມລະເມັດ. ຄົນທີ່ເກັບໄວ້ໃນຄັງຂອງຕົນໄດ້ຫຼາຍກວ່າຊະນະ. ຄົນໃນຫ້ອງເບິ່ງຢູ່.',
