  'Cargos automáticos': 'ບົດບາດອັດຕະໂນມັດ',
  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': 'ສ້າງບົດບາດຂອງຊຸມຊົນກ່ອນ ໃນ ສະມາຊິກ. ຈາກນັ້ນກັບມາບ່ອນນີ້ ເພື່ອໃຫ້ມັນແຈກເອງອັດຕະໂນມັດ.',
  'Cargo de quem entra': 'ບົດບາດຂອງຄົນທີ່ເຂົ້າມາໃໝ່',
  'Toda pessoa nova recebe estes cargos ao entrar na comunidade.': 'ທຸກຄົນທີ່ເຂົ້າມາໃໝ່ຈະໄດ້ຮັບບົດບາດເຫຼົ່ານີ້ ເມື່ອເຂົ້າຮ່ວມຊຸມຊົນ.',
  'Cargos por reação': 'ບົດບາດຕາມການຕອບສະໜອງ',
  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'Syden ຈະໂພສຂໍ້ຄວາມໃນຊ່ອງ ພ້ອມອີໂມຈິໜຶ່ງອັນຕໍ່ບົດບາດໜຶ່ງ. ຜູ້ທີ່ຕອບສະໜອງຈະໄດ້ບົດບາດ; ຜູ້ທີ່ເອົາການຕອບສະໜອງອອກຈະເສຍບົດບາດນັ້ນ.',
