  'Escolha os seus cargos reagindo aqui embaixo!': 'ເລືອກບົດບາດຂອງເຈົ້າໂດຍການຕອບສະໜອງຂ້າງລຸ່ມ!',
  'Texto do painel': 'ຂໍ້ຄວາມຂອງແຜງ',
  'Emoji {n}': 'ອີໂມຈິ {n}',
