  'Mais um emoji': 'ອີໂມຈິອີກອັນ',
  'Publicar o painel': 'ໂພສແຜງ',
  'Quais jogos a turma joga, com quantas pessoas e quantas partidas vão até o fim. Só contagem: respostas e desenhos não são guardados. Conta a partir de 12/10/2026.': 'ກຸ່ມຫຼິ້ນເກມຫຍັງແດ່ ກັບຄົນຈັກຄົນ ແລະ ມີຈັກຮອບທີ່ຫຼິ້ນຈົນຈົບ. ນັບຈຳນວນເທົ່ານັ້ນ: ຄຳຕອບ ແລະ ຮູບແຕ້ມບໍ່ຖືກເກັບໄວ້. ນັບຕັ້ງແຕ່ 12/10/2026.',
