  'O som': 'ສຽງ',
  'A música': 'ເພງ',
  'O emoji': 'ອີໂມຈິ',
  'O arquivo': 'ໄຟລ໌',
  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) ຖືກເອົາອອກຈາກ Syden ເພາະ {quem} ແຈ້ງວ່າເປັນເຈົ້າຂອງສິດ. ຖ້າເຈົ້າໄດ້ຮັບອະນຸຍາດໃຫ້ເຜີຍແຜ່, ຕອບກັບບ່ອນນີ້ເພື່ອອະທິບາຍ: ຄຳຕອບຂອງເຈົ້າຈະຖືກພິຈາລະນາ. ຈົນກວ່າເລື່ອງນີ້ຈະແຈ້ງ, ມັນຈະຍັງຖືກເອົາອອກຢູ່. ຂໍ້ກຳນົດອະທິບາຍວິທີເຮັດວຽກໃນພາກທີ 4: https://syden.chat/termos.html#direito-autoral',
  '«{nome}» saiu.': '«{nome}» ຖືກເອົາອອກແລ້ວ.',
  'Saíram junto {n} cópia(s) do mesmo arquivo.': 'ສຳເນົາຂອງໄຟລ໌ດຽວກັນທີ່ຖືກເອົາອອກພ້ອມກັນ: {n}',
  'Quem subiu recebeu o aviso numa conversa com você.': 'ຜູ້ອັບໂຫຼດໄດ້ຮັບແຈ້ງເຕືອນໃນການສົນທະນາກັບເຈົ້າແລ້ວ.',
  'Não havia a quem avisar.': 'ບໍ່ມີໃຜໃຫ້ແຈ້ງ.',
  'É a retirada número {n} desta pessoa.': 'ນີ້ແມ່ນການເອົາອອກຄັ້ງທີ {n} ຂອງຄົນນີ້.',
  'Direito autoral': 'ລິຂະສິດ',
  'Quem tem o direito escreve para direitos@syden.chat dizendo o que é e onde está. Procure pelo nome, retire, e quem subiu recebe o aviso numa conversa com você, onde pode contestar.': 'ເຈົ້າຂອງສິດຂຽນຫາ direitos@syden.chat ບອກວ່າແມ່ນຫຍັງ ແລະ ຢູ່ໃສ. ຄົ້ນຫາຕາມຊື່, ເອົາອອກ, ແລ້ວຜູ້ອັບໂຫຼດຈະໄດ້ຮັບແຈ້ງເຕືອນໃນການສົນທະນາກັບເຈົ້າ ເຊິ່ງສາມາດໂຕ້ແຍ້ງໄດ້ຢູ່ທີ່ນັ້ນ.',
  'Nome do som, da música, do emoji ou do arquivo': 'ຊື່ສຽງ, ເພງ, ອີໂມຈິ ຫຼື ໄຟລ໌',
