  'Desligar esta conta': 'ຕັດການເຊື່ອມບັນຊີນີ້',
  'Ele entra no Syden com a conta dele (ou cria uma) e abre Configurações → Família.': 'ລາວເຂົ້າ Syden ດ້ວຍບັນຊີຂອງລາວ (ຫຼື ສ້າງໃໝ່) ແລ້ວເປີດ ການຕັ້ງຄ່າ → ຄອບຄົວ.',
