  'Esta conta já está ligada a um responsável.': 'ບັນຊີນີ້ເຊື່ອມກັບຜູ້ປົກຄອງຄົນໜຶ່ງແລ້ວ.',
  'Esta transmissão não está disponível para você.': 'ສະຕຣີມນີ້ບໍ່ມີໃຫ້ທ່ານ.',
  'Falta ligar a sua conta a um pai, mãe ou responsável. Até lá, as proteções ficam todas ligadas.': 'ບັນຊີຂອງທ່ານຍັງບໍ່ໄດ້ເຊື່ອມກັບພໍ່, ແມ່ ຫຼື ຜູ້ປົກຄອງ. ຈົນກວ່າຈະເຊື່ອມ, ການປົກປ້ອງທັງໝົດຈະເປີດຢູ່.',
