  'Motivo:': 'ເຫດຜົນ:',
  'Na conta dele, em Configurações → Família, aparece um código. Digite aqui.': 'ໃນບັນຊີຂອງລາວ, ທີ່ ການຕັ້ງຄ່າ → ຄອບຄົວ, ມີລະຫັດສະແດງ. ພິມມັນຢູ່ນີ້.',
  'Não deu para gerar o arquivo agora. Tente de novo.': 'ສ້າງໄຟລ໌ບໍ່ໄດ້ຕອນນີ້. ລອງໃໝ່.',
