  'Olhar para trás': 'ເບິ່ງຫຼັງ',
  'Setas para dirigir, Espaço para derrapar, E para usar o item.': 'ລູກສອນເພື່ອບັງຄັບ, ຍະຫວ່າງເພື່ອດຣິຟ, E ເພື່ອໃຊ້ໄອເທັມ.',
