  'Vidas': 'ຊີວິດ',
  'Você não está nesta subida.': 'ບໍ່ໄດ້ຢູ່ໃນຮອບປີນນີ້.',
  'Estoura-balão': 'ລູກໂປ່ງແຕກ',
  'Coelhos a jato': 'ກະຕ່າຍເຈັດ',
  'A corrida está andando.': 'ການແຂ່ງຂັນກຳລັງດຳເນີນຢູ່.',
  'Cidade à noite': 'ເມືອງຍາມກາງຄືນ',
  'Órbita': 'ວົງໂຄຈອນ',
  'Mar de nuvens': 'ທະເລເມກ',
  'Quantos adversários do computador?': 'ຄູ່ແຂ່ງຄອມພິວເຕີຈັກຄົນ?',
  'Balões': 'ລູກໂປ່ງ',
  'Pegue as caixas e estoure os balões dos outros. Quem fica sem balão sai.': 'ເກັບກ່ອງແລ້ວເຮັດໃຫ້ລູກໂປ່ງຂອງຄົນອື່ນແຕກ. ໃຜບໍ່ມີລູກໂປ່ງເຫຼືອຈະຕົກຮອບ.',
  'Sem balões: agora é assistir. ◀ ▶ trocam de quem.': 'ບໍ່ມີລູກໂປ່ງແລ້ວ: ຕອນນີ້ໄດ້ແຕ່ເບິ່ງ. ◀ ▶ ປ່ຽນຄົນທີ່ເບິ່ງ.',
  'Você venceu!': 'ຊະນະ!',
  '{posicao}º lugar, entre {total}': 'ອັນດັບ {posicao} ຈາກ {total}',
  'Balões que sobraram: {n}': 'ລູກໂປ່ງທີ່ເຫຼືອ: {n}',
  'Balões estourados: {n}': 'ລູກໂປ່ງທີ່ເຮັດແຕກ: {n}',
  'Freio de ar': 'ເບຣກອາກາດ',
  'Turbo': 'ເທີໂບ',
  'Pilotar': 'ບັງຄັບ',
  'Turbo (da segunda volta em diante)': 'ເທີໂບ (ຕັ້ງແຕ່ຮອບທີສອງ)',
  '{n} voltas': '{n} ຮອບ',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'ພະລັງງານຄືຊີວິດ ແລະ ເທີໂບ: ຕຳຂອບຈະເສຍພະລັງງານ, ແຖບສີບົວຈະສາກຄືນ.',
  'A nave explodiu: a energia acabou.': 'ຍານລະເບີດ: ພະລັງງານໝົດ.',
  'Posição: {posicao} de {total}': 'ອັນດັບ: {posicao} ຈາກ {total}',
  'Escolher a pista': 'ເລືອກສະໜາມ',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'ແຂ່ງຍານຮູບກາລົດເທິງສະໜາມທີ່ລອຍຢູ່ກາງອາກາດ, ໄວກວ່າລົດໂກຄາດຫຼາຍ. ພະລັງງານຄືຊີວິດ ແລະ ເທີໂບ: ຕຳຂອບຈະເສຍພະລັງງານ, ແຖບສີບົວຈະສາກຄືນ, ແລະ ອອກຈາກສະໜາມຄືຕົກ. ຫຼິ້ນຄົນດຽວ: ແຂ່ງກັບເວລາ ແລະ ຜີຂອງໝູ່.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'ລົດໂກຄາດໃນສະໜາມປິດ, ແຕ່ລະຄັນມີລູກໂປ່ງສາມໜ່ວຍ. ເກັບກ່ອງແລ້ວໃຊ້ໄອເທັມເຮັດໃຫ້ລູກໂປ່ງຂອງຄົນອື່ນແຕກ: ໃຜບໍ່ມີລູກໂປ່ງເຫຼືອຈະຕົກຮອບ, ແລະ ຄົນທີ່ຢູ່ລອດຄົນສຸດທ້າຍຊະນະ.',
  'Esquadrilha da toca': 'ກອງບິນໂພງ',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'ເຮືອບິນແຄລອດນ້ອຍໆ ຕ້ານແມງໄມ້ສວນຜັກ: ຫຼົບເມັດພືດ, ເກັບການເສີມກຳລັງ ແລະ ຍິງຫຸ່ນໄລ່ກາກົນຈັກໃຫ້ຕົກໃນຕອນທ້າຍ. ກຸ່ມບິນຄື້ນດຽວກັນ ແລະ ຄະແນນຂອງກອງບິນຖືກລວມກັນ.',
  'O espantalho caiu!': 'ຫຸ່ນໄລ່ກາຕົກແລ້ວ!',
  'A praga venceu desta vez.': 'ເທື່ອນີ້ແມງໄມ້ຊະນະ.',
  'Placar da esquadrilha: {n}': 'ຄະແນນກອງບິນ: {n}',
  'Esquadrilha: {n}': 'ກອງບິນ: {n}',
  'Vidas: {n}': 'ຊີວິດ: {n}',
  'Bombas: {n}': 'ລະເບີດ: {n}',
  'Bomba': 'ລະເບີດ',
  'Voar': 'ບິນ',
  'Desvie das sementes e derrube a praga. O espantalho vem no fim.': 'ຫຼົບເມັດພືດ ແລະ ຍິງແມງໄມ້ໃຫ້ຕົກ. ຫຸ່ນໄລ່ກາມາຕອນທ້າຍ.',
  'Sem vidas: agora é torcer pela esquadrilha.': 'ໝົດຊີວິດແລ້ວ: ຕອນນີ້ເຊຍກອງບິນ.',
  'Assistindo: {nome}': 'ກຳລັງເບິ່ງ: {nome}',
  'A população está no máximo: construa uma Casa.': 'ພົນລະເມືອງເຕັມແລ້ວ: ສ້າງເຮືອນ.',
  'A fila está cheia.': 'ແຖວເຕັມແລ້ວ.',
