  'Estratégia em tempo real contra o computador: colete comida, madeira e ouro, construa a vila, avance de era e treine o exército. Ganha quem derrubar o centro da vila do outro, ou construir a Maravilha e mantê-la de pé por 2 minutos.': 'ເກມວາງແຜນແບບທັນທີກັບຄອມພິວເຕີ: ເກັບອາຫານ, ໄມ້ ແລະ ຄຳ, ສ້າງບ້ານ, ເລື່ອນຍຸກ ແລະ ຝຶກກອງທັບ. ຜູ້ທີ່ທຳລາຍສູນກາງບ້ານຂອງອີກຝ່າຍ, ຫຼື ສ້າງສິ່ງມະຫັດສະຈັນ ແລະ ຮັກສາໄວ້ໄດ້ 2 ນາທີ ຈະຊະນະ.',
