  'A sua Maravilha ficou de pé por 2 minutos.': 'ສິ່ງມະຫັດສະຈັນຂອງເຈົ້າຕັ້ງຢູ່ໄດ້ 2 ນາທີ.',
  'A Maravilha do computador ficou de pé por 2 minutos.': 'ສິ່ງມະຫັດສະຈັນຂອງຄອມພິວເຕີຕັ້ງຢູ່ໄດ້ 2 ນາທີ.',
