  'O computador derrubou o seu centro da vila.': 'ຄອມພິວເຕີທຳລາຍສູນກາງບ້ານຂອງເຈົ້າ.',
  'Você avançou para a era 2!': 'ເຈົ້າເລື່ອນສູ່ຍຸກ 2 ແລ້ວ!',
  'O computador avançou para a era 2.': 'ຄອມພິວເຕີເລື່ອນສູ່ຍຸກ 2 ແລ້ວ.',
  'A sua Maravilha está pronta: defenda-a por 2 minutos!': 'ສິ່ງມະຫັດສະຈັນຂອງເຈົ້າພ້ອມແລ້ວ: ປົກປ້ອງໄວ້ 2 ນາທີ!',
  'O computador terminou uma Maravilha: derrube-a em 2 minutos!': 'ຄອມພິວເຕີສ້າງສິ່ງມະຫັດສະຈັນແລ້ວ: ທຳລາຍມັນໃຫ້ໄດ້ໃນ 2 ນາທີ!',
  'A sua vila está sob ataque!': 'ບ້ານຂອງເຈົ້າຖືກໂຈມຕີ!',
  'Escolher': 'ເລືອກ',
  'Botão direito: mandar': 'ຄລິກຂວາ: ສັ່ງການ',
