  'Os dois estão pondo os navios…': 'ທັງສອງຝ່າຍກຳລັງວາງເຮືອ…',
  'Navio de {n} casas': 'ເຮືອ {n} ຊ່ອງ',
  'Seus navios': 'ເຮືອຂອງເຈົ້າ',
  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'ເລືອກເຮືອແລ້ວແຕະທະເລ. ລາກເພື່ອຍ້າຍ.',
  'Sortear a frota': 'ສຸ່ມກອງເຮືອ',
  'Sua frota já está pronta.': 'ກອງເຮືອຂອງເຈົ້າພ້ອມແລ້ວ.',
  'Ponha todos os navios antes.': 'ວາງເຮືອໃຫ້ຄົບກ່ອນ.',
  'Escolha um navio.': 'ເລືອກເຮືອ.',
  'O navio não cabe aí.': 'ເຮືອວາງບ່ອນນັ້ນບໍ່ໄດ້.',
  'Os navios não podem encostar um no outro.': 'ເຮືອຕ້ອງບໍ່ຕິດກັນ.',
  'Minigolfe 3D': 'ມິນິກອຟ 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'ແປດຂຸມແບບ 3D ມີທາງລາດ, ປາສາດ ແລະ ກັງຫັນລົມ, ທຸກຄົນຫຼິ້ນຂຸມດຽວກັນພ້ອມກັນ. ລາກເພື່ອເລັງ ແລະ ໃຫ້ແຮງ, ແລ້ວປ່ອຍ. ຜູ້ທີ່ຕີລວມໜ້ອຍທີ່ສຸດຊະນະ.',
  'Ver o buraco de cima': 'ເບິ່ງຂຸມຈາກດ້ານເທິງ',
  'Fora da pista! Mais uma tacada.': 'ອອກນອກທາງ! ຕີເພີ່ມອີກໜຶ່ງເທື່ອ.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'ລາກໄປທາງຂ້າງເພື່ອເລັງ ແລະ ລາກລົງເພື່ອແຮງ, ແລ້ວປ່ອຍ. ໃນແປ້ນພິມ: ລູກສອນເພື່ອເລັງ, ແລະ ກົດຍະຫວ່າງຄ້າງໄວ້ໃຫ້ແຮງ.',
  'Futebol dos coelhos': 'ບານເຕະກະຕ່າຍ',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'ບານເຕະສະໜາມນ້ອຍ, ເບິ່ງຈາກເທິງ. ແຕະບານເພື່ອເລາະບານ, ກົດຍະຫວ່າງຄ້າງໄວ້ເພື່ອຍິງແຮງຂຶ້ນ ແລະ ສົ່ງບານດ້ວຍ X. ໃນຫ້ອງ, ທີມຈະຖືກເຕີມໃຫ້ຄົບດ້ວຍຫຸ່ນຍົນ.',
  'Quantos por time?': 'ທີມລະຈັກຄົນ?',
  'Seu time venceu!': 'ທີມຂອງເຈົ້າຊະນະ!',
  'Seu time perdeu.': 'ທີມຂອງເຈົ້າເສຍ.',
