  'Chutar': 'ຍິງ',
  'Chutar (segure para mais força)': 'ຍິງ (ກົດຄ້າງໄວ້ເພື່ອແຮງຫຼາຍຂຶ້ນ)',
  'Gol!': 'ປະຕູ!',
  'Gol contra': 'ຍິງເຂົ້າປະຕູຕົວເອງ',
  'Partida inválida.': 'ການແຂ່ງຂັນບໍ່ຖືກຕ້ອງ.',
  'Ninguém para jogar.': 'ບໍ່ມີໃຜຫຼິ້ນ.',
  'Caça às pragas da horta': 'ລ່າແມງໄມ້ສວນຜັກ',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'ກາ ແລະ ຕັກແຕນ ກຳລັງໂຈມຕີສວນຜັກ. ເລັງ ແລະ ຄລິກ ເພື່ອຍິງໃຫ້ຖືກກ່ອນມັນໜີ: ລູກປືນມີຈຳກັດ ແລະ ແຕ່ລະຄື້ນມາໄວຂຶ້ນ. ຜູ້ທີ່ໄດ້ຄະແນນຫຼາຍທີ່ສຸດຊະນະ.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'ເລັງ ແລະ ຄລິກໃສ່ແມງໄມ້ກ່ອນມັນໜີ. ຍິງແຕ່ລະນັດໃຊ້ກາລົດໜຶ່ງຫົວ.',
