  'Setas para mover, Espaço para trocar, X para subir a pilha.': 'ລູກສອນເພື່ອເຄື່ອນທີ່, ຍະຫວ່າງເພື່ອສະຫຼັບ, X ເພື່ອຍົກກອງຂຶ້ນ.',
  'A horta está salva!': 'ສວນຜັກປອດໄພແລ້ວ!',
  'A horta caiu.': 'ສວນຜັກພັງແລ້ວ.',
  'Campanha': 'ການຜະຈົນໄພ',
  'Sem vidas.': 'ໝົດຊີວິດແລ້ວ.',
