  'Pular': 'ກະໂດດ',
  'Bater': 'ຕີ',
  'Neste buraco': 'ໃນຂຸມນີ້',
  'Total': 'ລວມ',
  'Tacadas: {n}': 'ຈຳນວນຕີ: {n}',
  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'ດຶງບານໄປທາງຫຼັງແລ້ວປ່ອຍ. ໃນແປ້ນພິມ: ລູກສອນເພື່ອເລັງ, ແລະ ກົດຍະຫວ່າງຄ້າງໄວ້ໃຫ້ແຮງ.',
  'Na água! Mais uma tacada.': 'ຕົກນ້ຳ! ຕີເພີ່ມອີກໜຶ່ງເທື່ອ.',
  'No buraco!': 'ລົງຂຸມ!',
  'Acabaram as tacadas.': 'ໝົດການຕີແລ້ວ.',
