  '{nome} ainda está no engarrafamento.': '{nome} ຍັງຕິດຢູ່ໃນລົດຕິດ.',
  '{nome} vendeu prédios e hipotecou cidades para pagar ({valor}).': '{nome} ຂາຍຕຶກ ແລະ ຈຳນອງເມືອງເພື່ອຈ່າຍ ({valor}).',
  '{nome} faliu e as cidades voltaram ao banco.': '{nome} ລົ້ມລະລາຍ ແລະ ເມືອງກັບຄືນໄປເປັນຂອງທະນາຄານ.',
  '{nome} faliu, e tudo o que tinha foi para {outro}.': '{nome} ລົ້ມລະລາຍ ແລະ ທຸກຢ່າງທີ່ມີຕົກເປັນຂອງ {outro}.',
  '{nome} e {outro} fecharam uma troca.': '{nome} ແລະ {outro} ຕົກລົງແລກປ່ຽນກັນແລ້ວ.',
