  'Quem para aqui tira uma notícia.': 'ໃຜຢຸດບ່ອນນີ້ຕ້ອງຈົກຂ່າວໜຶ່ງໃບ.',
  'Um descanso: aqui não acontece nada.': 'ພັກຜ່ອນ: ບ່ອນນີ້ບໍ່ມີຫຍັງເກີດຂຶ້ນ.',
