  'Até quando?': 'ຫຼິ້ນຮອດເມື່ອໃດ?',
  'rodadas': 'ຮອບ',
  'Até sobrar um': 'ຈົນເຫຼືອຄົນດຽວ',
  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'ຍ່າງໄປຕາມນະຄອນຫຼວງຂອງລັດຕ່າງໆໃນບຣາຊິນ ຊື້ເມືອງ ແລະ ເກັບຄ່າເຊົ່າຈາກຄົນທີ່ຢຸດຢູ່ບ່ອນນັ້ນ. ຖ້າມີທັງພາກກໍສ້າງຕຶກໄດ້. ແລກປ່ຽນ, ແຂ່ງກັນໃນການປະມູນ ແລະ ຢ່າໃຫ້ເງິນໝົດ.',
  'Trocar a foto': 'ປ່ຽນຮູບ',
  'Pôr uma foto': 'ໃສ່ຮູບ',
  'Tirar a foto': 'ເອົາຮູບອອກ',
  'A foto só aparece depois de salvar o recado.': 'ຮູບຈະສະແດງຫຼັງຈາກບັນທຶກປະກາດແລ້ວເທົ່ານັ້ນ.',
  'Figurinhas': 'ສະຕິກເກີ',
  'Figurinha não encontrada.': 'ບໍ່ພົບສະຕິກເກີ.',
  'A sua coleção de figurinhas está cheia. Tire alguma para pôr outra.': 'ຄໍເລັກຊັນສະຕິກເກີຂອງເຈົ້າເຕັມແລ້ວ. ເອົາອອກສັກອັນກ່ອນຈຶ່ງໃສ່ອັນໃໝ່ໄດ້.',
  'Figurinha': 'ສະຕິກເກີ',
  'Salva nas suas figurinhas': 'ບັນທຶກໄວ້ໃນສະຕິກເກີຂອງເຈົ້າແລ້ວ',
  'Não deu para salvar': 'ບັນທຶກບໍ່ໄດ້',
  'Salvar figurinha': 'ບັນທຶກສະຕິກເກີ',
  'Essa imagem é grande demais para virar figurinha (até 1 MB).': 'ຮູບນີ້ໃຫຍ່ເກີນໄປທີ່ຈະເຮັດເປັນສະຕິກເກີ (ບໍ່ເກີນ 1 MB).',
  'Use uma imagem PNG, JPG, GIF ou WEBP.': 'ໃຊ້ຮູບ PNG, JPG, GIF ຫຼື WEBP.',
  'Arrumar': 'ຈັດການ',
  'Criar figurinha': 'ສ້າງສະຕິກເກີ',
  'Tirar o fundo': 'ລຶບພື້ນຫຼັງ',
  'Contorno': 'ເສັ້ນຂອບ',
  'O fundo não é de uma cor só, e ficou como veio.': 'ພື້ນຫຼັງບໍ່ແມ່ນສີດຽວ ຈຶ່ງປະໄວ້ຄືເກົ່າ.',
  'No app do Syden, o recorte funciona com qualquer fundo.': 'ໃນແອັບ Syden ລຶບພື້ນຫຼັງໃດກໍໄດ້.',
  'O recorte com o modelo falhou, e ficou o recorte simples.': 'ການລຶບດ້ວຍໂມເດວບໍ່ສຳເລັດ ຈຶ່ງໃຊ້ການລຶບແບບງ່າຍ.',
  'Mandar figurinha': 'ສົ່ງສະຕິກເກີ',
  'Tirar figurinha': 'ເອົາສະຕິກເກີອອກ',
  'Crie figurinhas com as suas imagens, ou salve as que receber numa conversa.': 'ສ້າງສະຕິກເກີຈາກຮູບຂອງເຈົ້າ ຫຼື ບັນທຶກສະຕິກເກີທີ່ໄດ້ຮັບໃນການສົນທະນາ.',
  'Dominó': 'ໂດມິໂນ',
  'Truco': 'ທຣູໂກ',
  'Damas': 'ໝາກຮອດ',
  'Batalha naval': 'ເກມເຮືອຮົບ',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'ໂດມິໂນແບບທີ່ຄຸ້ນເຄີຍ ຫຼິ້ນໄດ້ 2 ຫາ 4 ຄົນ (4 ຄົນຫຼິ້ນເປັນຄູ່). ຕໍ່ໂດມິໂນທີ່ປາຍ, ໃຜລົງໝົດກ່ອນໄດ້ຄະແນນໃນມືຂອງຄົນອື່ນ.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'ທຣູໂກແບບບຣາຊິນ, ມີໄພ້ຫງາຍ ແລະ ໄພ້ແຮງ, ຫຼິ້ນ 2 ຄົນ ຫຼື ເປັນຄູ່ 4 ຄົນ. ຂໍທຣູໂກ, ເພີ່ມເປັນຫົກ, ເກົ້າ ແລະ ສິບສອງ, ຫຼື ໜີ. ໃຜໄດ້ 12 ຄະແນນຊະນະ.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'ໝາກຮອດແບບບຣາຊິນ: ຕ້ອງກິນສະເໝີ, ທັງໄປໜ້າ ແລະ ຖອຍຫຼັງ, ແລະ ໂຕຮອດເດີນໄດ້ຕະຫຼອດເສັ້ນຂວາງ. ຫ້ອງເບິ່ງຢູ່.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'ແຕ່ລະຄົນເຊື່ອງກອງເຮືອຂອງຕົນ ແລະ ຍິງໃສ່ທະເລຂອງອີກຝ່າຍ. ຍິງຖືກ, ຍິງອີກ. ໃຜຈົມກອງເຮືອທັງໝົດກ່ອນຊະນະ. ຫ້ອງເບິ່ງຢູ່.',
