  'Mão de onze: jogar valendo 3, ou correr e dar 1 ponto?': 'ມືສິບເອັດ: ຫຼິ້ນທີ່ 3 ຄະແນນ, ຫຼື ໜີ ແລະ ໃຫ້ 1 ຄະແນນ?',
