  'Já atiraram no seu mar: a frota não muda mais.': 'ມີຄົນຍິງທະເລຂອງເຈົ້າແລ້ວ: ປ່ຽນກອງເຮືອບໍ່ໄດ້ອີກ.',
  'Esse lance não vale.': 'ຍ່າງແບບນີ້ບໍ່ໄດ້.',
  'Esse lance não vale mais.': 'ການຍ່າງນີ້ໃຊ້ບໍ່ໄດ້ແລ້ວ.',
  'O truco é jogado em 2 ou em 4.': 'ທຣູໂກຫຼິ້ນ 2 ຫຼື 4 ຄົນ.',
  'Não há mão de onze agora.': 'ຕອນນີ້ບໍ່ມີມືສິບເອັດ.',
  'Quem decide a mão de onze é quem tem 11.': 'ຝ່າຍທີ່ມີ 11 ຄະແນນເປັນຜູ້ຕັດສິນມືສິບເອັດ.',
  'Não há pedido de truco agora.': 'ຕອນນີ້ບໍ່ມີການຂໍທຣູໂກ.',
  'Quem responde é o outro lado.': 'ອີກຝ່າຍເປັນຜູ້ຕອບ.',
  'Não dá para aumentar mais.': 'ເພີ່ມອີກບໍ່ໄດ້ແລ້ວ.',
  'Espere a resposta do truco.': 'ລໍຖ້າຄຳຕອບທຣູໂກກ່ອນ.',
  'Agora não dá para pedir truco.': 'ຕອນນີ້ຂໍທຣູໂກບໍ່ໄດ້.',
  'Essa carta não está na sua mão.': 'ໄພ້ໃບນີ້ບໍ່ຢູ່ໃນມືເຈົ້າ.',
  'A carta coberta só vale da segunda rodada em diante.': 'ໄພ້ຄວ່ຳໃຊ້ໄດ້ຕັ້ງແຕ່ຮອບທີສອງເປັນຕົ້ນໄປ.',
  'Espere a próxima mão.': 'ລໍຖ້າມືຕໍ່ໄປ.',
  'Você tem uma pedra que serve.': 'ເຈົ້າມີໂຕທີ່ຕໍ່ໄດ້.',
  'Não há pedras para comprar.': 'ບໍ່ມີໂຕໃຫ້ຈົກແລ້ວ.',
  'Compre uma pedra antes de passar.': 'ຈົກກ່ອນ ແລ້ວຈຶ່ງຜ່ານ.',
  'Essa pedra não está na sua mão.': 'ໂຕນີ້ບໍ່ຢູ່ໃນມືເຈົ້າ.',
  'A primeira pedra é outra.': 'ໂຕທຳອິດຕ້ອງເປັນໂຕອື່ນ.',
  'Essa pedra não encaixa na mesa.': 'ໂຕນີ້ຕໍ່ເທິງໂຕະບໍ່ໄດ້.',
