  'Quantos adversários?': 'ຄູ່ແຂ່ງຈັກຄົນ?',
  'Estilo visual': 'ຮູບແບບການສະແດງຜົນ',
  'C para trocar na vertical.': 'C ເພື່ອສັບປ່ຽນຕາມແນວຕັ້ງ.',
