  Bispo: 'ບິດຊອບ',
  'Cozinha da toca': 'ເຮືອນຄົວໃນຮູ',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'ເອົາວັດຖຸດິບຈາກລັງ, ຫັ່ນຢູ່ເທິງຂຽງ, ປຸງຢູ່ເທິງເຕົາ ແລະ ໃນເຕົາອົບໂດຍບໍ່ໃຫ້ໄໝ້, ຈັດໃສ່ຈານ ແລ້ວສົ່ງຢູ່ປ່ອງຢ້ຽມ. ທຸກຄົນໄດ້ຮັບອໍເດີດຽວກັນ: ຜູ້ທີ່ສົ່ງຈານໄດ້ຫຼາຍທີ່ສຸດໃນ 3 ນາທີຊະນະ.',
  'Pegar ou largar': 'ຍົກ ຫຼື ວາງ',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'ເກມນີ້ຕ້ອງການກຣາບຟິກ 3D ເຊິ່ງບໍ່ເປີດໃນອຸປະກອນນີ້.',
  'Este prato não é o pedido.': 'ຈານນີ້ບໍ່ແມ່ນອໍເດີ.',
