  "Diagnóstico do host": "ການວິນິດໄສໂຮສ",
  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "ບັນທຶກແບບຈຳກັດຂອງ Docker, SSH, logind ແລະ ເຄີເນວ ຈາກການບູດສາມຄັ້ງຫຼ້າສຸດ. ອາດມີທີ່ຢູ່ IP.",
  "Atualizar diagnóstico": "ໂຫຼດການວິນິດໄສຄືນ",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "ຍັງບໍ່ມີສະແນັບຊັອດ. ຈະເກັບເມື່ອເປີດຕູ້ນິລະໄພຄັ້ງຕໍ່ໄປ.",
  "Coletado em {data}": "ເກັບເມື່ອ {data}",
  "Medido pela {nome}": "ວັດໂດຍ {nome}",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "ຕົວເລກດຽວກັນກັບແຜງຄວບຄຸມຂອງຜູ້ໃຫ້ບໍລິການ. ລວມເຖິງດິສກ໌ທີ່ເຊີບເວີບໍ່ໄດ້ວັດເອງ.",
  "Ações no servidor": "ການດຳເນີນການກັບເຊີບເວີ",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "ປະຫວັດຂອງ Hetzner: ເປີດ, ປິດ ແລະ ເລີ່ມໃໝ່ ຈາກແຜງຄວບຄຸມ ຫຼື API. ການລົ້ມທີ່ບໍ່ມີການດຳເນີນການຢູ່ນີ້ບໍ່ໄດ້ຖືກສັ່ງຜ່ານທາງເຫຼົ່ານີ້.",
  "Nenhuma ação registrada.": "ບໍ່ມີການດຳເນີນການທີ່ບັນທຶກໄວ້.",
  "Ligar o servidor": "ເປີດເຊີບເວີ",
  "Desligar o servidor": "ປິດເຊີບເວີ",
